examples.template:
HStack(spacing: theme.spacing.space1) {
    MonarchButton({{buttons.0.label}}, variant: .ghost, size: .sm) {}
    MonarchButton({{buttons.1.label}}, variant: .ghost, size: .sm) {}
    MonarchButton({{buttons.2.label}}, variant: .ghost, size: .sm) {}
        .disabled({{buttons.2.disabled}})
    MonarchButton({{buttons.3.label}}, variant: .ghost, size: .sm) {}
}
.accessibilityElement(children: .contain)
.accessibilityLabel({{label}})

examples.code:
HStack(spacing: theme.spacing.space1) {
    MonarchButton("Bold", variant: .ghost, size: .sm) {}
    MonarchButton("Italic", variant: .ghost, size: .sm) {}
    MonarchButton("Strikethrough", variant: .ghost, size: .sm) {}
        .disabled(true)
    MonarchButton("Link", variant: .ghost, size: .sm) {}
}
.accessibilityElement(children: .contain)
.accessibilityLabel("Text formatting")

HStack(spacing: theme.spacing.space2) {
    ForEach(0..<3, id: \.self) { index in
        Text("Swatch \(index + 1)")
            .monarchTextStyle(.label)
            .padding(theme.spacing.space3)
            .background(theme.colors.bgMuted, in: RoundedRectangle(cornerRadius: theme.radius.md))
            .focusable()
            .focused($focused, equals: index)
            .monarchFocusRing(focused == index, in: RoundedRectangle(cornerRadius: theme.radius.md))
    }
}
.onKeyPress(.rightArrow) { move(layoutDirection == .rightToLeft ? -1 : 1) }
.onKeyPress(.leftArrow) { move(layoutDirection == .rightToLeft ? 1 : -1) }

examples.setup:
@Environment(\.monarchTheme) private var theme
@Environment(\.layoutDirection) private var layoutDirection
@FocusState private var focused: Int?

private func move(_ step: Int) -> KeyPress.Result {
    guard let current = focused, (0..<3).contains(current + step) else { return .ignored }
    focused = current + step
    return .handled
}
